/** Entry for wrangler.inline.toml: same Worker, static site served from an inlined map instead of the ASSETS binding. */
import worker from "./index";
// @ts-ignore generated by scripts/gen_inline_assets.py
import { ASSETS_MAP } from "../build/inline/assets";
import { Env } from "./util";

const SEC = { "x-content-type-options": "nosniff", "referrer-policy": "strict-origin-when-cross-origin", "x-frame-options": "DENY" };
const inlineAssets = {
  async fetch(input: Request | string): Promise<Response> {
    const req = typeof input === "string" ? new Request(input) : input;
    let p = new URL(req.url).pathname;
    if (p.endsWith("/")) p += "index.html";
    const a = (ASSETS_MAP as Record<string, { t: string; b: string }>)[p] ?? (ASSETS_MAP as any)[p + ".html"];
    if (!a) return new Response("Not found", { status: 404 });
    const bin = Uint8Array.from(atob(a.b), (c) => c.charCodeAt(0));
    const cache = p === "/hero.webp" ? "public, max-age=604800" : "public, max-age=300";
    return new Response(req.method === "HEAD" ? null : bin, { headers: { "content-type": a.t, "cache-control": cache, ...SEC } });
  },
} as unknown as Fetcher;

export default {
  fetch(req: Request, env: Env, ctx: ExecutionContext) { return worker.fetch(req, { ...env, ASSETS: inlineAssets }, ctx); },
  scheduled(ev: ScheduledController, env: Env, ctx: ExecutionContext) { return worker.scheduled(ev, { ...env, ASSETS: inlineAssets }, ctx); },
};
